function getResult(arr, m) {
  const stack = [];
  const nextBigger = new Array(m).fill(-1);

  for (let i = 0; i < arr.length; i++) {
    while (stack.length) {
      const [idx, val] = stack.at(-1);
      if (arr[i] > val) {
        stack.pop();
        nextBigger[idx] = i;
      } else {
        break;
      }
    }
    stack.push([i, arr[i]]);
  }

  const ans = [];

  for (let i = 0; i < arr.length; i++) {
    const idx = nextBigger[i];

    if (idx === -1) {
      ans.push(arr[i]);
    } else {
      ans.push((idx - i) * (arr[idx] - arr[i])); // 距离 * 数字差值
    }
  }

  return ans.join(" ");
